#include <cmath>
#include <limits>

using FunctionPtr = double (*)(double);

double bisection_root_finder(FunctionPtr f, double a, double b, double precision, unsigned int max_iter) {
    // Check if a or b is already a root
    double fa = f(a);
    double fb = f(b);

    if (fa == 0.0) return a;
    if (fb == 0.0) return b;

    // Check if f(a) and f(b) have opposite signs
    if (fa * fb > 0.0) {
        return std::numeric_limits<double>::quiet_NaN();
    }

    // Bisection loop
    double c = a;
    for (unsigned int i = 0; i < max_iter; ++i) {
        c = (a + b) / 2.0;
        double fc = f(c);

        if (fc == 0.0 || (b - a) / 2.0 < precision) {
            return c;
        }

        if (fa * fc < 0.0) {
            b = c;
            fb = fc;
        } else {
            a = c;
            fa = fc;
        }
    }

    return (a + b) / 2.0;
}

// Test function
double test_func(double x) {
    return x * x - 2.0; // Root at x = sqrt(2)
}

int main() {
    double root = bisection_root_finder(test_func, 0.0, 2.0, 1e-6, 100);
    return 0;
}

